urlset:
{# ── Статические страницы ── #}

  https://buket.by/
  daily
  1.0


  https://buket.by/store/
  daily
  0.9


  https://buket.by/kontakty/
  monthly
  0.8


  https://buket.by/reviews/
  weekly
  0.7


  https://buket.by/p/dostavka/
  monthly
  0.8


  https://buket.by/p/oplata/
  monthly
  0.7


  https://buket.by/page/terms/
  yearly
  0.4


  https://buket.by/page/returns/
  yearly
  0.4


{# ── Категории ── #}
{% for cat in categories %}
{% if cat.slug %}

  https://buket.by/store/category/{{ cat.slug }}/
  weekly
  0.7

{% for child in cat.children.all %}
{% if child.slug %}

  https://buket.by/store/category/{{ child.slug }}/
  weekly
  0.6

{% endif %}
{% endfor %}
{% endif %}
{% endfor %}

{# ── Цветочные теги ── #}
{% for tag in flower_tags %}
{% if tag.slug %}

  https://buket.by/store/flower/{{ tag.slug }}/
  weekly
  0.6

{% endif %}
{% endfor %}

{# ── Товары ── #}
{% for product in products %}
{% if product.slug %}

  https://buket.by/store/{{ product.slug }}/
  {{ product.created_at|date:"Y-m-d" }}
  weekly
  0.8
  {% if product.uploaded_image %}

    https://buket.by{{ product.uploaded_image.url }}
    {{ product.title }}

  {% endif %}

{% endif %}
{% endfor %}
